#!/usr/bin/env node
// Validates every task directory beside this script:
//   - task.json has the required fields and matches the directory name
//   - the fixture as shipped fails `node --test test/*.test.js`
//   - the same fixture with src/ replaced by reference/src/ passes
//   - no node_modules is committed and the directory stays under 150 KB
// Prints one line per task and exits non-zero on any violation.
import { spawnSync } from 'node:child_process';
import { cpSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const MAX_BYTES = 150 * 1024;
const problems = [];

/** Recursively sum file sizes under `dir`. */
function dirBytes(dir) {
  let total = 0;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) total += dirBytes(full);
    else total += statSync(full).size;
  }
  return total;
}

/** Recursively collect files under `dir` matching `predicate`. */
function walk(dir, predicate, out = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, predicate, out);
    else if (predicate(full)) out.push(full);
  }
  return out;
}

/** Static count of `assert...` calls across a task's test files. */
function countAssertions(taskDir) {
  const files = walk(path.join(taskDir, 'test'), (f) => f.endsWith('.test.js'));
  let count = 0;
  for (const file of files) {
    const source = readFileSync(file, 'utf8');
    count += (source.match(/\bassert\s*(?:\.[A-Za-z]+)?\s*\(/g) ?? []).length;
  }
  return count;
}

/** Run the task's test command in `cwd`; returns the exit status. */
function runTests(cwd) {
  const result = spawnSync('sh', ['-c', 'node --test test/*.test.js'], {
    cwd,
    encoding: 'utf8',
    timeout: 180_000,
  });
  return { status: result.status, output: `${result.stdout ?? ''}${result.stderr ?? ''}` };
}

/** Copy a task fixture (everything but reference/) into a fresh temp directory. */
function materialise(taskDir) {
  const dest = mkdtempSync(path.join(tmpdir(), 'pg-validate-'));
  cpSync(taskDir, dest, {
    recursive: true,
    filter: (src) => path.relative(taskDir, src).split(path.sep)[0] !== 'reference',
  });
  return dest;
}

const REQUIRED_FIELDS = ['id', 'tier', 'domain', 'title', 'prompt', 'heldOut', 'immutable', 'checks'];

const taskDirs = readdirSync(root, { withFileTypes: true })
  .filter((e) => e.isDirectory() && !e.name.startsWith('.'))
  .map((e) => e.name)
  .sort();

for (const name of taskDirs) {
  const taskDir = path.join(root, name);
  const fail = (message) => problems.push(`${name}: ${message}`);

  let task;
  try {
    task = JSON.parse(readFileSync(path.join(taskDir, 'task.json'), 'utf8'));
  } catch (error) {
    fail(`unreadable task.json: ${error.message}`);
    continue;
  }
  for (const field of REQUIRED_FIELDS) {
    if (!(field in task)) fail(`task.json missing field: ${field}`);
  }
  if (task.id !== `code:${name}`) fail(`task.json id ${task.id} does not match directory`);
  if (![2, 3, 4].includes(task.tier)) fail(`task.json tier ${task.tier} is not 2, 3 or 4`);
  if (typeof task.prompt !== 'string' || task.prompt.length < 200) fail('task.json prompt is too short');
  if (typeof task.heldOut !== 'boolean') fail('task.json heldOut is not a boolean');
  if (!Array.isArray(task.immutable) || !task.immutable.includes('test')) fail('task.json immutable must list test');
  if (!Array.isArray(task.checks) || task.checks.length === 0) fail('task.json checks is empty');
  for (const check of task.checks ?? []) {
    for (const field of ['id', 'outcome', 'run']) {
      if (typeof check?.[field] !== 'string') fail(`check ${check?.id} missing ${field}`);
    }
  }
  if (/\btier\b|\bheld[- ]out\b|\breference solution\b/i.test(task.prompt ?? '')) {
    fail('task.json prompt leaks tier / held-out / reference wording');
  }

  const pkg = JSON.parse(readFileSync(path.join(taskDir, 'package.json'), 'utf8'));
  if (pkg.type !== 'module') fail('package.json is not type=module');
  if (pkg.name !== name) fail(`package.json name ${pkg.name} does not match directory`);
  if (pkg.dependencies || pkg.devDependencies) fail('package.json declares dependencies');

  if (readdirSync(taskDir).includes('node_modules')) fail('node_modules is present');
  const bytes = dirBytes(taskDir);
  if (bytes > MAX_BYTES) fail(`directory is ${bytes} bytes, over the 150 KB limit`);

  const referenceSrc = path.join(taskDir, 'reference', 'src');
  if (!statSync(referenceSrc, { throwIfNoEntry: false })?.isDirectory()) {
    fail('reference/src is missing');
    continue;
  }

  const preDir = materialise(taskDir);
  const pre = runTests(preDir);
  if (pre.status === 0) fail('pre-state test run unexpectedly passed');
  rmSync(preDir, { recursive: true, force: true });

  const refDir = materialise(taskDir);
  rmSync(path.join(refDir, 'src'), { recursive: true, force: true });
  cpSync(referenceSrc, path.join(refDir, 'src'), { recursive: true });
  const ref = runTests(refDir);
  if (ref.status !== 0) {
    fail(`reference test run failed:\n${ref.output.split('\n').slice(-40).join('\n')}`);
  }
  rmSync(refDir, { recursive: true, force: true });

  const assertions = countAssertions(taskDir);
  if (assertions < 25) fail(`only ${assertions} assertions, at least 25 required`);
  const preState = pre.status === 0 ? 'pass' : 'fail';
  const reference = ref.status === 0 ? 'pass' : 'fail';
  process.stdout.write(
    `${task.id} tier=${task.tier} preState=${preState} reference=${reference} assertions=${assertions} bytes=${bytes}\n`,
  );
}

if (problems.length > 0) {
  process.stderr.write(`\n${problems.length} problem(s):\n`);
  for (const problem of problems) process.stderr.write(`  - ${problem}\n`);
  process.exit(1);
}
process.stdout.write(`\nall ${taskDirs.length} task(s) validated\n`);

/**
 * Retry policy: configuration validation, error classification, backoff schedules
 * with full jitter, and a pure simulation of an attempt sequence.
 */

/** Error raised for invalid policy configuration and invalid simulation input. */
export class PolicyError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'PolicyError';
    this.code = code;
  }
}

const KNOWN_FIELDS = ['baseMs', 'maxAttempts', 'factor', 'maxDelayMs', 'budgetMs', 'jitter'];
const DEFAULTS = { factor: 2, maxDelayMs: 30000, budgetMs: Infinity, jitter: 'full' };

const RETRYABLE_CODES = new Set(['etimedout', 'econnreset', 'econnrefused', 'eai_again', 'epipe', 'enetunreach']);

/**
 * Validate a policy and fill in defaults.
 *
 * @param {unknown} input Raw policy configuration.
 * @returns {Readonly<{baseMs: number, maxAttempts: number, factor: number, maxDelayMs: number, budgetMs: number, jitter: string}>} Frozen policy.
 */
export function normalizePolicy(input) {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
    throw new PolicyError('INVALID_POLICY', 'policy must be an object');
  }
  for (const key of Object.keys(input)) {
    if (!KNOWN_FIELDS.includes(key)) {
      throw new PolicyError('UNKNOWN_FIELD', `unknown policy field: ${key}`);
    }
  }
  const policy = {};
  for (const name of ['baseMs', 'maxAttempts']) {
    const value = input[name];
    if (value === undefined) {
      throw new PolicyError('MISSING_FIELD', `missing required policy field: ${name}`);
    }
    if (!Number.isInteger(value) || value < 1) {
      throw new PolicyError('INVALID_FIELD', `invalid policy field: ${name}`);
    }
    policy[name] = value;
  }
  const factor = input.factor === undefined ? DEFAULTS.factor : input.factor;
  if (typeof factor !== 'number' || !Number.isFinite(factor) || factor < 1) {
    throw new PolicyError('INVALID_FIELD', 'invalid policy field: factor');
  }
  policy.factor = factor;

  const maxDelayMs = input.maxDelayMs === undefined ? DEFAULTS.maxDelayMs : input.maxDelayMs;
  if (!Number.isInteger(maxDelayMs) || maxDelayMs < 1) {
    throw new PolicyError('INVALID_FIELD', 'invalid policy field: maxDelayMs');
  }
  policy.maxDelayMs = maxDelayMs;

  const budgetMs = input.budgetMs === undefined ? DEFAULTS.budgetMs : input.budgetMs;
  if (budgetMs !== Infinity && (!Number.isInteger(budgetMs) || budgetMs < 0)) {
    throw new PolicyError('INVALID_FIELD', 'invalid policy field: budgetMs');
  }
  policy.budgetMs = budgetMs;

  const jitter = input.jitter === undefined ? DEFAULTS.jitter : input.jitter;
  if (jitter !== 'full' && jitter !== 'none') {
    throw new PolicyError('INVALID_FIELD', 'invalid policy field: jitter');
  }
  policy.jitter = jitter;

  return Object.freeze(policy);
}

/**
 * Decide whether a failure is worth retrying.
 *
 * @param {unknown} error Failure value produced by an attempt.
 * @returns {'retryable'|'permanent'} Classification.
 */
export function classifyError(error) {
  if (typeof error !== 'object' || error === null) return 'permanent';
  if (error.retryable === true) return 'retryable';
  if (error.retryable === false) return 'permanent';
  const status = error.status;
  if (typeof status === 'number' && Number.isInteger(status)) {
    if (status === 501) return 'permanent';
    if (status === 408 || status === 429) return 'retryable';
    if (status >= 500 && status <= 599) return 'retryable';
    return 'permanent';
  }
  const code = error.code;
  if (typeof code === 'string' && RETRYABLE_CODES.has(code.toLowerCase())) return 'retryable';
  return 'permanent';
}

/**
 * Uncapped-then-capped integer delay for a retry slot, before jitter.
 *
 * @param {{baseMs: number, factor: number, maxDelayMs: number}} policy Normalized policy.
 * @param {number} slot One-based retry slot.
 * @returns {number} Capped integer delay.
 */
function cappedDelay(policy, slot) {
  const raw = policy.baseMs * policy.factor ** (slot - 1);
  return Math.floor(Math.min(raw, policy.maxDelayMs));
}

/**
 * Draw the delay for one retry slot, consuming one value from `random` under full jitter.
 *
 * @param {object} policy Normalized policy.
 * @param {number} slot One-based retry slot.
 * @param {() => number} random Source of uniform values in [0, 1).
 * @returns {number} Delay in milliseconds.
 */
function drawDelay(policy, slot, random) {
  const capped = cappedDelay(policy, slot);
  if (policy.jitter === 'none') return capped;
  return Math.floor(random() * (capped + 1));
}

/**
 * Build the full backoff schedule for a policy.
 *
 * @param {unknown} policyInput Raw or normalized policy.
 * @param {() => number} random Source of uniform values in [0, 1).
 * @returns {{delays: number[], totalDelayMs: number, stopReason: 'attempts'|'budget'}} Schedule.
 */
export function computeSchedule(policyInput, random) {
  const policy = normalizePolicy(policyInput);
  if (typeof random !== 'function') {
    throw new PolicyError('INVALID_RANDOM', 'random must be a function');
  }
  const delays = [];
  let totalDelayMs = 0;
  let stopReason = 'attempts';
  for (let slot = 1; slot <= policy.maxAttempts - 1; slot += 1) {
    const delay = drawDelay(policy, slot, random);
    if (totalDelayMs + delay > policy.budgetMs) {
      stopReason = 'budget';
      break;
    }
    delays.push(delay);
    totalDelayMs += delay;
  }
  return { delays, totalDelayMs, stopReason };
}

/**
 * Simulate an attempt sequence against a fixed list of outcomes.
 *
 * @param {unknown} policyInput Raw or normalized policy.
 * @param {unknown} outcomes Outcome descriptors, one per attempt.
 * @param {() => number} random Source of uniform values in [0, 1).
 * @returns {object} Terminal result with the waits that were performed.
 */
export function planAttempts(policyInput, outcomes, random) {
  const policy = normalizePolicy(policyInput);
  if (typeof random !== 'function') {
    throw new PolicyError('INVALID_RANDOM', 'random must be a function');
  }
  if (!Array.isArray(outcomes) || outcomes.length === 0) {
    throw new PolicyError('INVALID_OUTCOMES', 'outcomes must be a non-empty array');
  }
  outcomes.forEach((outcome, index) => {
    if (typeof outcome !== 'object' || outcome === null || typeof outcome.ok !== 'boolean') {
      throw new PolicyError('INVALID_OUTCOMES', `outcome ${index} must have a boolean ok field`);
    }
  });

  const waits = [];
  let totalDelayMs = 0;
  for (let attempts = 1; ; attempts += 1) {
    const outcome = outcomes[attempts - 1];
    if (outcome === undefined) {
      throw new PolicyError('OUTCOMES_EXHAUSTED', 'outcome sequence exhausted');
    }
    if (outcome.ok) {
      return { status: 'succeeded', attempts, value: outcome.value, waits, totalDelayMs };
    }
    const fail = (reason) => ({ status: 'failed', reason, error: outcome.error, attempts, waits, totalDelayMs });
    if (classifyError(outcome.error) === 'permanent') return fail('permanent');
    if (attempts >= policy.maxAttempts) return fail('attempts');
    const delay = drawDelay(policy, attempts, random);
    if (totalDelayMs + delay > policy.budgetMs) return fail('budget');
    waits.push(delay);
    totalDelayMs += delay;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { PolicyError, classifyError, computeSchedule, normalizePolicy, planAttempts } from '../src/index.js';

/** Deterministic 32-bit PRNG so property loops replay identically. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** A random source that replays a fixed list and counts its own calls. */
function scripted(values) {
  const fn = () => {
    if (fn.calls >= values.length) throw new Error('scripted random exhausted');
    const value = values[fn.calls];
    fn.calls += 1;
    return value;
  };
  fn.calls = 0;
  return fn;
}

/** A random source returning a constant, counting its own calls. */
function constant(value) {
  const fn = () => {
    fn.calls += 1;
    return value;
  };
  fn.calls = 0;
  return fn;
}

test('normalizePolicy fills documented defaults and freezes the result', () => {
  const policy = normalizePolicy({ baseMs: 50, maxAttempts: 4 });
  assert.deepEqual(policy, { baseMs: 50, maxAttempts: 4, factor: 2, maxDelayMs: 30000, budgetMs: Infinity, jitter: 'full' });
  assert.equal(Object.isFrozen(policy), true);
  assert.deepEqual(Object.keys(policy).sort(), ['baseMs', 'budgetMs', 'factor', 'jitter', 'maxAttempts', 'maxDelayMs']);
});

test('normalizePolicy keeps explicit values including edge-legal ones', () => {
  const policy = normalizePolicy({ baseMs: 1, maxAttempts: 1, factor: 1, maxDelayMs: 1, budgetMs: 0, jitter: 'none' });
  assert.deepEqual(policy, { baseMs: 1, maxAttempts: 1, factor: 1, maxDelayMs: 1, budgetMs: 0, jitter: 'none' });
  assert.equal(normalizePolicy({ baseMs: 5, maxAttempts: 2, factor: 1.5 }).factor, 1.5);
  assert.equal(normalizePolicy({ baseMs: 5, maxAttempts: 2, budgetMs: Infinity }).budgetMs, Infinity);
});

test('normalizePolicy treats an explicit undefined as absent', () => {
  const policy = normalizePolicy({ baseMs: 5, maxAttempts: 2, factor: undefined, jitter: undefined });
  assert.equal(policy.factor, 2);
  assert.equal(policy.jitter, 'full');
  assert.throws(() => normalizePolicy({ baseMs: undefined, maxAttempts: 2 }), {
    name: 'PolicyError',
    code: 'MISSING_FIELD',
    message: 'missing required policy field: baseMs',
  });
});

test('normalizePolicy rejects malformed configuration with exact codes', () => {
  const cases = [
    [null, 'INVALID_POLICY', 'policy must be an object'],
    ['nope', 'INVALID_POLICY', 'policy must be an object'],
    [[], 'INVALID_POLICY', 'policy must be an object'],
    [{ baseMs: 1, maxAttempts: 1, retries: 3 }, 'UNKNOWN_FIELD', 'unknown policy field: retries'],
    [{ maxAttempts: 3 }, 'MISSING_FIELD', 'missing required policy field: baseMs'],
    [{ baseMs: 10 }, 'MISSING_FIELD', 'missing required policy field: maxAttempts'],
    [{ baseMs: 0, maxAttempts: 3 }, 'INVALID_FIELD', 'invalid policy field: baseMs'],
    [{ baseMs: 1.5, maxAttempts: 3 }, 'INVALID_FIELD', 'invalid policy field: baseMs'],
    [{ baseMs: '10', maxAttempts: 3 }, 'INVALID_FIELD', 'invalid policy field: baseMs'],
    [{ baseMs: 10, maxAttempts: 0 }, 'INVALID_FIELD', 'invalid policy field: maxAttempts'],
    [{ baseMs: 10, maxAttempts: 3, factor: 0.5 }, 'INVALID_FIELD', 'invalid policy field: factor'],
    [{ baseMs: 10, maxAttempts: 3, factor: Infinity }, 'INVALID_FIELD', 'invalid policy field: factor'],
    [{ baseMs: 10, maxAttempts: 3, maxDelayMs: 0 }, 'INVALID_FIELD', 'invalid policy field: maxDelayMs'],
    [{ baseMs: 10, maxAttempts: 3, budgetMs: -1 }, 'INVALID_FIELD', 'invalid policy field: budgetMs'],
    [{ baseMs: 10, maxAttempts: 3, budgetMs: 1.5 }, 'INVALID_FIELD', 'invalid policy field: budgetMs'],
    [{ baseMs: 10, maxAttempts: 3, jitter: 'half' }, 'INVALID_FIELD', 'invalid policy field: jitter'],
  ];
  for (const [input, code, message] of cases) {
    assert.throws(() => normalizePolicy(input), { name: 'PolicyError', code, message }, `case ${JSON.stringify(input)}`);
  }
  assert.equal(new PolicyError('X', 'y') instanceof Error, true);
});

test('normalizePolicy reports an unknown field before a missing one', () => {
  assert.throws(() => normalizePolicy({ tries: 4 }), { code: 'UNKNOWN_FIELD', message: 'unknown policy field: tries' });
});

test('classifyError applies the documented precedence', () => {
  const cases = [
    [{ retryable: true, status: 404 }, 'retryable'],
    [{ retryable: false, status: 503 }, 'permanent'],
    [{ retryable: 'yes' }, 'permanent'],
    [{ status: 500 }, 'retryable'],
    [{ status: 502 }, 'retryable'],
    [{ status: 599 }, 'retryable'],
    [{ status: 501 }, 'permanent'],
    [{ status: 408 }, 'retryable'],
    [{ status: 429 }, 'retryable'],
    [{ status: 400 }, 'permanent'],
    [{ status: 499 }, 'permanent'],
    [{ status: 600 }, 'permanent'],
    [{ status: 503.5, code: 'ETIMEDOUT' }, 'retryable'],
    [{ status: Number.NaN, code: 'ENOENT' }, 'permanent'],
    [{ status: 404, code: 'ECONNRESET' }, 'permanent'],
    [{ code: 'ETIMEDOUT' }, 'retryable'],
    [{ code: 'econnreset' }, 'retryable'],
    [{ code: 'EAI_AGAIN' }, 'retryable'],
    [{ code: 'EPIPE' }, 'retryable'],
    [{ code: 'ENETUNREACH' }, 'retryable'],
    [{ code: 'ECONNREFUSED' }, 'retryable'],
    [{ code: 'ENOENT' }, 'permanent'],
    [{ code: 'ETIMEDOUT_EXTRA' }, 'permanent'],
    [{}, 'permanent'],
    [null, 'permanent'],
    [undefined, 'permanent'],
    ['ETIMEDOUT', 'permanent'],
    [42, 'permanent'],
  ];
  for (const [error, expected] of cases) {
    assert.equal(classifyError(error), expected, `case ${JSON.stringify(error)}`);
  }
  const wrapped = Object.assign(new Error('socket hang up'), { code: 'ECONNRESET' });
  assert.equal(classifyError(wrapped), 'retryable');
});

test('computeSchedule grows geometrically and never calls random without jitter', () => {
  const random = constant(0.5);
  const schedule = computeSchedule({ baseMs: 100, maxAttempts: 5, jitter: 'none' }, random);
  assert.deepEqual(schedule.delays, [100, 200, 400, 800]);
  assert.equal(schedule.totalDelayMs, 1500);
  assert.equal(schedule.stopReason, 'attempts');
  assert.equal(random.calls, 0);
  assert.deepEqual(computeSchedule({ baseMs: 100, maxAttempts: 1, jitter: 'none' }, random).delays, []);
});

test('computeSchedule caps and floors each delay', () => {
  const random = constant(0);
  assert.deepEqual(
    computeSchedule({ baseMs: 100, maxAttempts: 5, maxDelayMs: 300, jitter: 'none' }, random).delays,
    [100, 200, 300, 300],
  );
  assert.deepEqual(
    computeSchedule({ baseMs: 100, maxAttempts: 5, factor: 1.5, jitter: 'none' }, random).delays,
    [100, 150, 225, 337],
  );
  assert.deepEqual(
    computeSchedule({ baseMs: 7, maxAttempts: 4, factor: 1, jitter: 'none' }, random).delays,
    [7, 7, 7],
  );
});

test('computeSchedule stops on the first delay that would overrun the budget', () => {
  const base = { baseMs: 100, maxAttempts: 5, jitter: 'none' };
  const exact = computeSchedule({ ...base, budgetMs: 300 }, constant(0));
  assert.deepEqual(exact.delays, [100, 200]);
  assert.equal(exact.totalDelayMs, 300);
  assert.equal(exact.stopReason, 'budget');

  const short = computeSchedule({ ...base, budgetMs: 299 }, constant(0));
  assert.deepEqual(short.delays, [100]);
  assert.equal(short.stopReason, 'budget');

  const roomy = computeSchedule({ ...base, budgetMs: 1500 }, constant(0));
  assert.deepEqual(roomy.delays, [100, 200, 400, 800]);
  assert.equal(roomy.stopReason, 'attempts');
});

test('full jitter draws exactly one value per slot from the given source', () => {
  const random = scripted([0, 0.5, 0.25, 0.999]);
  const schedule = computeSchedule({ baseMs: 100, maxAttempts: 5 }, random);
  assert.deepEqual(schedule.delays, [0, 100, 100, 800]);
  assert.equal(random.calls, 4);
  assert.equal(schedule.totalDelayMs, 1000);
});

test('a slot rejected by the budget still consumes its draw', () => {
  const random = constant(0.9);
  const schedule = computeSchedule({ baseMs: 1000, maxAttempts: 5, budgetMs: 0 }, random);
  assert.deepEqual(schedule.delays, []);
  assert.equal(schedule.stopReason, 'budget');
  assert.equal(random.calls, 1);
});

test('computeSchedule rejects a missing random source and invalid policies', () => {
  assert.throws(() => computeSchedule({ baseMs: 1, maxAttempts: 2 }, null), {
    name: 'PolicyError',
    code: 'INVALID_RANDOM',
    message: 'random must be a function',
  });
  assert.throws(() => computeSchedule({ baseMs: -1, maxAttempts: 2 }, constant(0)), { code: 'INVALID_FIELD' });
});

test('planAttempts stops at the first success', () => {
  const random = constant(0);
  const result = planAttempts(
    { baseMs: 10, maxAttempts: 4, jitter: 'none' },
    [{ ok: false, error: { status: 503 } }, { ok: true, value: 'body' }],
    random,
  );
  assert.equal(result.status, 'succeeded');
  assert.equal(result.attempts, 2);
  assert.equal(result.value, 'body');
  assert.deepEqual(result.waits, [10]);
  assert.equal(result.totalDelayMs, 10);
});

test('planAttempts gives up immediately on a permanent failure', () => {
  const random = constant(0);
  const result = planAttempts(
    { baseMs: 10, maxAttempts: 5, jitter: 'none' },
    [{ ok: false, error: { status: 400 } }, { ok: true, value: 'unused' }],
    random,
  );
  assert.equal(result.status, 'failed');
  assert.equal(result.reason, 'permanent');
  assert.equal(result.attempts, 1);
  assert.deepEqual(result.waits, []);
  assert.deepEqual(result.error, { status: 400 });
  assert.equal(random.calls, 0);
});

test('planAttempts exhausts the attempt count and then the budget', () => {
  const retryable = { ok: false, error: { code: 'ETIMEDOUT' } };
  const byAttempts = planAttempts({ baseMs: 10, maxAttempts: 3, jitter: 'none' }, [retryable, retryable, retryable], constant(0));
  assert.equal(byAttempts.reason, 'attempts');
  assert.equal(byAttempts.attempts, 3);
  assert.deepEqual(byAttempts.waits, [10, 20]);

  const byBudget = planAttempts(
    { baseMs: 100, maxAttempts: 6, budgetMs: 250, jitter: 'none' },
    Array.from({ length: 6 }, () => retryable),
    constant(0),
  );
  assert.equal(byBudget.reason, 'budget');
  assert.deepEqual(byBudget.waits, [100]);
  assert.equal(byBudget.attempts, 2);
});

test('planAttempts validates its outcome list', () => {
  const policy = { baseMs: 1, maxAttempts: 9 };
  assert.throws(() => planAttempts(policy, [], constant(0)), {
    code: 'INVALID_OUTCOMES',
    message: 'outcomes must be a non-empty array',
  });
  assert.throws(() => planAttempts(policy, 'nope', constant(0)), { code: 'INVALID_OUTCOMES' });
  assert.throws(() => planAttempts(policy, [{ ok: true }, { value: 1 }], constant(0)), {
    code: 'INVALID_OUTCOMES',
    message: 'outcome 1 must have a boolean ok field',
  });
  assert.throws(() => planAttempts(policy, [{ ok: false, error: { status: 500 } }], constant(0)), {
    code: 'OUTCOMES_EXHAUSTED',
    message: 'outcome sequence exhausted',
  });
