/**
 * Fixed-width plain-text tables: display width, wrapping, padding and layout.
 */

/** Error raised for invalid table input. */
export class TableError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'TableError';
    this.code = code;
  }
}

/**
 * Display width of a string in terminal columns.
 *
 * @param {string} text Text to measure.
 * @returns {number} Column count.
 */
export function stringWidth(text) {
  throw new Error('not implemented');
}

/**
 * Wrap cell text to a column width.
 *
 * @param {string} text Cell text; explicit newlines start a new line.
 * @param {number} width Column width in display columns.
 * @returns {string[]} Wrapped lines, at least one.
 */
export function wrapCell(text, width) {
  throw new Error('not implemented');
}

/**
 * Pad a single line to an exact display width.
 *
 * @param {string} text Line that already fits.
 * @param {number} width Target column width.
 * @param {'left'|'right'|'center'} [align] Alignment, left by default.
 * @returns {string} Padded line.
 */
export function padCell(text, width, align = 'left') {
  throw new Error('not implemented');
}

/**
 * Render rows as a fixed-width table.
 *
 * @param {string[][]} rows Rows of cells.
 * @param {{widths: number[], align?: string[], header?: boolean}} options Layout options.
 * @returns {string} Table text without a trailing newline.
 */
export function formatTable(rows, options) {
  throw new Error('not implemented');
}

{
  "id": "code:table-format",
  "tier": 2,
  "domain": "text",
  "title": "Fixed-width text tables with wrapping and wide-character widths",
  "prompt": "Implement `src/index.js` so it exports `TableError`, `stringWidth`, `wrapCell`, `padCell` and `formatTable`. `TableError` extends `Error`, sets `name` to `'TableError'`, carries a `code` string, and is constructed as `(code, message)`. Everything below measures text in terminal columns, never in code units, so iterate by code point.\n\n`stringWidth(text)` returns the column count of a string, throwing `'BAD_CELL'` with message `cell must be a string` for a non-string. A code point below U+0020, U+007F, any of U+200B, U+200C, U+200D and U+FEFF, or anything in U+0300 to U+036F counts as 0 columns. A code point in any of these inclusive ranges counts as 2 columns: U+1100-U+115F, U+2E80-U+303E, U+3041-U+33FF, U+3400-U+4DBF, U+4E00-U+9FFF, U+A000-U+A4CF, U+AC00-U+D7A3, U+F900-U+FAFF, U+FE10-U+FE19, U+FE30-U+FE6F, U+FF00-U+FF60, U+FFE0-U+FFE6, U+1F300-U+1F64F, U+1F900-U+1F9FF, U+20000-U+2FFFD and U+30000-U+3FFFD. Everything else counts as 1.\n\n`wrapCell(text, width)` returns the lines a cell occupies in a column of `width` columns, always at least one line, and never a line wider than `width`. `width` must be an integer of at least 1 (`'BAD_WIDTH'`, `width must be a positive integer`) and `text` must be a string (`'BAD_CELL'`, `cell must be a string`). The text is first split on newlines and each piece wrapped on its own, so an empty piece contributes one empty line. Within a piece, runs of one or more spaces separate words and collapse to a single space; leading and trailing spaces disappear, and a piece with no words yields one empty line. A word wider than the column is broken greedily into chunks of at most `width` columns, so a 2-column character that would straddle the edge starts the next chunk and leaves the previous one a column short; a single character wider than the whole column throws `'UNWRAPPABLE'` with message `character is wider than the column`. Words and chunks are then packed greedily, one space between neighbours on the same line, starting a new line whenever the next word would push the line past `width`.\n\n`padCell(text, width, align)` pads one already-fitting line to exactly `width` columns, with `align` defaulting to `'left'` and also accepting `'right'` and `'center'`; centring puts the smaller half of the padding on the left. It throws `'BAD_CELL'` for a non-string, `'BAD_WIDTH'` with message `width must be a positive integer` for a bad width, `'BAD_ALIGN'` with message `unknown alignment: <align>` for anything else, and `'CELL_TOO_WIDE'` with message `content is wider than the column` when the text does not fit. `formatTable(rows, options)` renders `rows`, an array of arrays of strings, using `options.widths` (an array of positive integers, one per column), the optional `options.align` (one alignment per column, all `'left'` by default) and the optional boolean `options.header`. Validation runs in this order, each failure throwing immediately: `options` must be a non-null object (`'BAD_OPTIONS'`, `options must be an object`); `widths` must be a non-empty array of positive integers (`'BAD_WIDTH'`, `widths must be a non-empty array of positive integers`); `align`, when given, must be an array of the same length (`'BAD_ALIGN'`, `align must have <n> entries`) holding known alignments (`'BAD_ALIGN'`, `unknown alignment: <value>`); `rows` must be an array (`'BAD_ROWS'`, `rows must be an array`); and each row, in order, must have one cell per column (`'BAD_ROW_LENGTH'`, `row <i> has <n> cells, expected <m>`, counting a non-array row as 0 cells) with every cell a string (`'BAD_CELL'`, `cell at row <i>, column <j> is not a string`). No rows renders the empty string. Otherwise every cell is wrapped to its column, a row occupies as many lines as its tallest cell with the shorter cells padded out with blanks, and the cells of one line are padded and joined with ` | `. When `header` is true a rule of hyphens per column joined with `-+-` follows the first row. Lines are joined with newlines, with no trailing newline, and every line of the result has the same display width.",
  "heldOut": false,
  "immutable": ["test", "package.json"],
  "checks": [
    { "id": "tests-pass", "outcome": "the test suite passes", "run": "node --test test/*.test.js" },
    { "id": "no-dependencies", "outcome": "no packages were installed", "run": "test ! -e node_modules" }
  ]
}

/**
 * Pure POSIX-style path arithmetic: no filesystem access, no working directory.
 */

/** Error raised for malformed paths and impossible requests. */
export class PathError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'PathError';
    this.code = code;
  }
}

/**
 * Reject non-strings and embedded NUL bytes.
 *
 * @param {unknown} value Candidate path or segment.
 * @returns {string} The validated string.
 */
function checkString(value) {
  if (typeof value !== 'string') throw new PathError('NOT_A_STRING', 'path must be a string');
  if (value.includes('�')) throw new PathError('NUL_BYTE', 'path contains a NUL byte');
  return value;
}

/**
 * Report whether a path starts at the root.
 *
 * @param {string} path Path to inspect.
 * @returns {boolean} True for a rooted path.
 */
export function isAbsolute(path) {
  return checkString(path).startsWith('/');
}

/**
 * Collapse `.`, `..`, repeated slashes and trailing slashes.
 *
 * @param {string} path Path to normalize.
 * @returns {string} Normalized path.
 */
export function normalize(path) {
  const input = checkString(path);
  if (input === '') throw new PathError('EMPTY_PATH', 'path must not be empty');
  const rooted = input.startsWith('/');
  const stack = [];
  for (const segment of input.split('/')) {
    if (segment === '' || segment === '.') continue;
    if (segment !== '..') {
      stack.push(segment);
      continue;
    }
    if (stack.length > 0 && stack[stack.length - 1] !== '..') {
      stack.pop();
    } else if (rooted) {
      throw new PathError('ESCAPE', `path escapes root: ${input}`);
    } else {
      stack.push('..');
    }
  }
  if (rooted) return `/${stack.join('/')}`;
  return stack.length === 0 ? '.' : stack.join('/');
}

/**
 * Join segments and normalize the result.
 *
 * @param {...string} segments One or more path segments.
 * @returns {string} Normalized joined path.
 */
export function join(...segments) {
  if (segments.length === 0) {
    throw new PathError('NO_SEGMENTS', 'join requires at least one segment');
  }
  segments.forEach((segment, index) => {
    checkString(segment);
    if (segment === '') throw new PathError('EMPTY_SEGMENT', `segment ${index} must not be empty`);
    if (index > 0 && segment.startsWith('/')) {
      throw new PathError('ABSOLUTE_SEGMENT', `segment ${index} must be relative`);
    }
  });
  return normalize(segments.join('/'));
}

/**
 * Path from one absolute location to another.
 *
 * @param {string} from Absolute starting path.
 * @param {string} to Absolute destination path.
 * @returns {string} Relative path, empty when the two are the same.
 */
export function relative(from, to) {
  checkString(from);
  checkString(to);
  if (!from.startsWith('/') || !to.startsWith('/')) {
    throw new PathError('NOT_ABSOLUTE', 'both paths must be absolute');
  }
  const fromParts = normalize(from).split('/').filter((part) => part !== '');
  const toParts = normalize(to).split('/').filter((part) => part !== '');
  let common = 0;
  while (common < fromParts.length && common < toParts.length && fromParts[common] === toParts[common]) {
    common += 1;
  }
  const up = fromParts.slice(common).map(() => '..');
  return [...up, ...toParts.slice(common)].join('/');
}

