/**
 * Append-only log framing: CRC-checked, length-prefixed records that survive
 * being cut off at an arbitrary byte.
 */

/** Error raised for invalid store or log input. */
export class StoreError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'StoreError';
    this.code = code;
  }
}

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let index = 0; index < 256; index += 1) {
    let value = index;
    for (let bit = 0; bit < 8; bit += 1) {
      value = value & 1 ? (value >>> 1) ^ 0xedb88320 : value >>> 1;
    }
    table[index] = value >>> 0;
  }
  return table;
})();

/** Header size in bytes: a big-endian length followed by a big-endian CRC. */
export const HEADER_BYTES = 8;

/**
 * Standard CRC-32 (reflected, polynomial 0xEDB88320).
 *
 * @param {Uint8Array} bytes Payload to checksum.
 * @returns {number} Unsigned 32-bit checksum.
 */
export function crc32(bytes) {
  if (!(bytes instanceof Uint8Array)) throw new StoreError('BAD_INPUT', 'bytes must be a Uint8Array');
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ byte) & 0xff];
  }
  return (crc ^ 0xffffffff) >>> 0;
}

/**
 * Report whether a decoded payload is a well-formed record.
 *
 * @param {unknown} record Candidate record.
 * @returns {boolean} True when the record can be applied.
 */
export function isRecord(record) {
  if (typeof record !== 'object' || record === null || Array.isArray(record)) return false;
  if (typeof record.k !== 'string' || record.k === '') return false;
  if (record.t === 'put') return 'v' in record;
  return record.t === 'del';
}

/**
 * Frame one record.
 *
 * @param {{t: string, k: string, v?: unknown}} record Record to encode.
 * @returns {Uint8Array} Framed bytes.
 */
export function encodeRecord(record) {
  if (!isRecord(record)) throw new StoreError('BAD_RECORD', 'record must be a put or del entry');
  const payload = new TextEncoder().encode(JSON.stringify(record));
  const frame = new Uint8Array(HEADER_BYTES + payload.length);
  const view = new DataView(frame.buffer);
  view.setUint32(0, payload.length, false);
  view.setUint32(4, crc32(payload), false);
  frame.set(payload, HEADER_BYTES);
  return frame;
}

/**
 * Decode every intact record at the front of a log.
 *
 * Never throws for well-typed input: a torn or corrupted frame simply ends the scan.
 *
 * @param {Uint8Array} bytes Log bytes, possibly truncated mid-frame.
 * @returns {{records: object[], bytesUsed: number, truncated: boolean}} Decoded prefix.
 */
export function decodeLog(bytes) {
  if (!(bytes instanceof Uint8Array)) throw new StoreError('BAD_INPUT', 'bytes must be a Uint8Array');
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const decoder = new TextDecoder();
  const records = [];
  let offset = 0;
  let truncated = false;
  while (offset < bytes.length) {
    if (bytes.length - offset < HEADER_BYTES) {
      truncated = true;
      break;
    }
    const length = view.getUint32(offset, false);
    if (bytes.length - offset - HEADER_BYTES < length) {
      truncated = true;
      break;
    }
    const payload = bytes.subarray(offset + HEADER_BYTES, offset + HEADER_BYTES + length);
    if (crc32(payload) !== view.getUint32(offset + 4, false)) {
      truncated = true;
      break;
    }
    let record;
    try {
      record = JSON.parse(decoder.decode(payload));
    } catch {
      // A frame whose payload is not JSON is indistinguishable from a torn tail.
      truncated = true;
      break;
    }
    if (!isRecord(record)) {
      truncated = true;
      break;
    }
    records.push(record);
    offset += HEADER_BYTES + length;
  }
  return { records, bytesUsed: offset, truncated };
}

/**
 * A key-value store whose only durable form is an append-only log.
 */
import { StoreError, decodeLog, encodeRecord } from './log.js';

const MAX_DEPTH = 32;

/**
 * Report whether a value is representable as JSON without loss.
 *
 * @param {unknown} value Candidate value.
 * @param {number} [depth] Current nesting depth.
 * @returns {boolean} True when the value round-trips through JSON unchanged.
 */
function isJsonValue(value, depth = 0) {
  if (depth > MAX_DEPTH) return false;
  if (value === null) return true;
  const kind = typeof value;
  if (kind === 'string' || kind === 'boolean') return true;
  if (kind === 'number') return Number.isFinite(value);
  if (Array.isArray(value)) return value.every((item) => isJsonValue(item, depth + 1));
  if (kind !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) return false;
  return Object.values(value).every((item) => isJsonValue(item, depth + 1));
}

/**
 * Copy a validated JSON value so stored state never aliases caller state.
 *
 * @param {unknown} value Value to copy.
 * @returns {unknown} Structural copy.
 */
function clone(value) {
  return value === null || typeof value !== 'object' ? value : JSON.parse(JSON.stringify(value));
}

/**
 * Reject keys that cannot be logged.
 *
 * @param {unknown} key Candidate key.
 * @returns {string} The validated key.
 */
function checkKey(key) {
  if (typeof key !== 'string' || key === '') {
    throw new StoreError('BAD_KEY', 'key must be a non-empty string');
  }
  return key;
}

/** Key-value store backed by an in-memory append-only log. */
export class KvStore {
  #map = new Map();

  #chunks = [];

  #bytes = 0;

  #records = 0;

  /**
   * Append one framed record and apply it.
   *
   * @param {{t: string, k: string, v?: unknown}} record Record to append.
   * @returns {void}
   */
  #append(record) {
    const frame = encodeRecord(record);
    this.#chunks.push(frame);
    this.#bytes += frame.length;
    this.#records += 1;
    if (record.t === 'put') this.#map.set(record.k, record.v);
    else this.#map.delete(record.k);
  }

  /**
   * Store a value, appending a record to the log.
   *
   * @param {string} key Non-empty key.
   * @param {unknown} value Any JSON-representable value.
   * @returns {KvStore} This store, for chaining.
   */
  put(key, value) {
    checkKey(key);
    if (!isJsonValue(value)) throw new StoreError('BAD_VALUE', 'value is not serializable');
    this.#append({ t: 'put', k: key, v: clone(value) });
    return this;
  }

  /**
   * Remove a key, appending a record only when the key is present.
   *
   * @param {string} key Non-empty key.
   * @returns {boolean} True when the key existed.
   */
  delete(key) {
    checkKey(key);
    if (!this.#map.has(key)) return false;
    this.#append({ t: 'del', k: key });
    return true;
  }

  /**
   * Read a value.
   *
   * @param {string} key Non-empty key.
   * @returns {unknown} A copy of the stored value, or undefined.
   */
  get(key) {
    checkKey(key);
    return this.#map.has(key) ? clone(this.#map.get(key)) : undefined;
  }

  /**
   * Test for a key.
   *
   * @param {string} key Non-empty key.
   * @returns {boolean} True when the key is present.
   */
  has(key) {
    return this.#map.has(checkKey(key));
  }

  /** @returns {number} Number of live keys. */
  get size() {
    return this.#map.size;
  }

  /** @returns {string[]} Live keys in ascending order. */
  keys() {
    return [...this.#map.keys()].sort();
  }

  /** @returns {Array<[string, unknown]>} Live entries in ascending key order. */
  entries() {
    return this.keys().map((key) => [key, clone(this.#map.get(key))]);
  }

  /** @returns {Uint8Array} A copy of the current log. */
  get log() {
    const out = new Uint8Array(this.#bytes);
    let offset = 0;
    for (const chunk of this.#chunks) {
      out.set(chunk, offset);
      offset += chunk.length;
    }
    return out;
  }

  /** @returns {{records: number, liveKeys: number, deadRecords: number}} Log occupancy. */
  stats() {
    return { records: this.#records, liveKeys: this.#map.size, deadRecords: this.#records - this.#map.size };
  }

  /**
   * Rewrite the log as one put per live key in ascending key order.
   *
   * @returns {{before: number, after: number, reclaimed: number}} Byte counts.
   */
  compact() {
    const before = this.#bytes;
    const chunks = [];
    let bytes = 0;
    for (const key of this.keys()) {
      const frame = encodeRecord({ t: 'put', k: key, v: this.#map.get(key) });
      chunks.push(frame);
      bytes += frame.length;
    }
    this.#chunks = chunks;
    this.#bytes = bytes;
    this.#records = chunks.length;
    return { before, after: bytes, reclaimed: before - bytes };
  }

  /** @returns {{version: number, entries: Array<[string, unknown]>}} Portable snapshot. */
  snapshot() {
    return { version: 1, entries: this.entries() };
  }

  /**
   * Rebuild a store from the intact prefix of a log.
   *
   * @param {Uint8Array} bytes Log bytes, possibly torn or corrupted.
   * @returns {KvStore} Store holding the state of that prefix.
   */
  static replay(bytes) {
    const { records, bytesUsed } = decodeLog(bytes);
    const store = new KvStore();
    for (const record of records) {
      if (record.t === 'put') store.#map.set(record.k, record.v);
      else store.#map.delete(record.k);
    }
    const kept = bytes.slice(0, bytesUsed);
    store.#chunks = kept.length === 0 ? [] : [kept];
    store.#bytes = kept.length;
    store.#records = records.length;
    return store;
  }

  /**
   * Rebuild a store from a snapshot, producing a compact log.
   *
   * @param {{version: number, entries: Array<[string, unknown]>}} snapshot Snapshot to load.
   * @returns {KvStore} Store holding the snapshot state.
   */
  static fromSnapshot(snapshot) {
    if (typeof snapshot !== 'object' || snapshot === null || Array.isArray(snapshot)) {
      throw new StoreError('BAD_SNAPSHOT', 'snapshot must be an object');
    }
    if (snapshot.version !== 1) throw new StoreError('BAD_SNAPSHOT', 'unsupported snapshot version');
    if (!Array.isArray(snapshot.entries)) throw new StoreError('BAD_SNAPSHOT', 'snapshot entries must be an array');
    const pairs = new Map();
    for (const entry of snapshot.entries) {
      if (!Array.isArray(entry) || entry.length !== 2) {
        throw new StoreError('BAD_SNAPSHOT', 'each snapshot entry must be a key and a value');
      }
      const [key, value] = entry;
      checkKey(key);
      if (!isJsonValue(value)) throw new StoreError('BAD_VALUE', 'value is not serializable');
      if (pairs.has(key)) throw new StoreError('BAD_SNAPSHOT', `duplicate key in snapshot: ${key}`);
      pairs.set(key, value);
    }
    const store = new KvStore();
    for (const key of [...pairs.keys()].sort()) store.put(key, pairs.get(key));
    return store;
  }
}

/**
 * Public surface of the log-backed key-value store.
 */
export { HEADER_BYTES, StoreError, crc32, decodeLog, encodeRecord, isRecord } from './log.js';
export { KvStore } from './store.js';

import test from 'node:test';
import assert from 'node:assert/strict';
import { HEADER_BYTES, crc32, decodeLog, encodeRecord, isRecord } from '../src/index.js';

/** Deterministic 32-bit PRNG so generated logs replay identically. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const utf8 = (text) => new TextEncoder().encode(text);

/** Concatenate framed records into one log. */
function buildLog(records) {
  const frames = records.map((record) => encodeRecord(record));
  const total = frames.reduce((sum, frame) => sum + frame.length, 0);
  const log = new Uint8Array(total);
  let offset = 0;
  for (const frame of frames) {
    log.set(frame, offset);
    offset += frame.length;
  }
  return log;
}

test('crc32 matches the standard vectors', () => {
  assert.equal(HEADER_BYTES, 8);
  assert.equal(crc32(new Uint8Array(0)), 0);
  assert.equal(crc32(utf8('a')), 0xe8b7be43);
  assert.equal(crc32(utf8('123456789')), 0xcbf43926);
  assert.equal(crc32(utf8('The quick brown fox jumps over the lazy dog')), 0x414fa339);
  assert.equal(crc32(new Uint8Array([0, 0, 0, 0])), 0x2144df1c);
  assert.ok(crc32(utf8('abc')) >= 0, 'checksums are unsigned');
  assert.throws(() => crc32([1, 2, 3]), { name: 'StoreError', code: 'BAD_INPUT' });
});

test('isRecord accepts only applicable records', () => {
  const cases = [
    [{ t: 'put', k: 'a', v: 1 }, true],
    [{ t: 'put', k: 'a', v: null }, true],
    [{ t: 'del', k: 'a' }, true],
    [{ t: 'put', k: 'a' }, false],
    [{ t: 'put', k: '', v: 1 }, false],
    [{ t: 'del', k: '' }, false],
    [{ t: 'set', k: 'a', v: 1 }, false],
    [{ k: 'a', v: 1 }, false],
    [null, false],
    [['put', 'a', 1], false],
    ['put a 1', false],
  ];
  for (const [record, expected] of cases) {
    assert.equal(isRecord(record), expected, `isRecord(${JSON.stringify(record)})`);
  }
});

test('encodeRecord writes a length and checksum header', () => {
  const record = { t: 'put', k: 'alpha', v: { n: 1 } };
  const frame = encodeRecord(record);
  const payload = frame.subarray(HEADER_BYTES);
  const view = new DataView(frame.buffer, frame.byteOffset, frame.byteLength);
  assert.equal(view.getUint32(0, false), payload.length);
  assert.equal(view.getUint32(4, false), crc32(payload));
  assert.equal(frame.length, HEADER_BYTES + payload.length);
  assert.deepEqual(JSON.parse(new TextDecoder().decode(payload)), record);
  assert.equal(encodeRecord({ t: 'del', k: 'alpha' }).length < frame.length, true);
});

test('encodeRecord rejects records that cannot be applied', () => {
  assert.throws(() => encodeRecord({ t: 'put', k: 'a' }), { code: 'BAD_RECORD' });
  assert.throws(() => encodeRecord({ t: 'nope', k: 'a', v: 1 }), { code: 'BAD_RECORD' });
  assert.throws(() => encodeRecord({ t: 'put', k: '', v: 1 }), { code: 'BAD_RECORD' });
  assert.throws(() => encodeRecord(null), { code: 'BAD_RECORD' });
});

test('decodeLog round-trips a whole log', () => {
  const records = [
    { t: 'put', k: 'a', v: 1 },
    { t: 'put', k: 'b', v: { deep: [1, 'two', null] } },
    { t: 'del', k: 'a' },
    { t: 'put', k: '日本', v: 'ünïcodé' },
  ];
  const log = buildLog(records);
  const decoded = decodeLog(log);
  assert.deepEqual(decoded.records, records);
  assert.equal(decoded.bytesUsed, log.length);
  assert.equal(decoded.truncated, false);
  assert.deepEqual(decodeLog(new Uint8Array(0)), { records: [], bytesUsed: 0, truncated: false });
  assert.throws(() => decodeLog('not bytes'), { code: 'BAD_INPUT', message: 'bytes must be a Uint8Array' });
});

test('decoding stops cleanly at every truncation point', () => {
  const records = [
    { t: 'put', k: 'a', v: 'first' },
    { t: 'put', k: 'bb', v: [1, 2, 3] },
    { t: 'del', k: 'a' },
    { t: 'put', k: 'c', v: true },
  ];
  const log = buildLog(records);
  const boundaries = new Set([0]);
  let running = 0;
  for (const record of records) {
    running += encodeRecord(record).length;
    boundaries.add(running);
  }
  let previous = 0;
  for (let cut = 0; cut <= log.length; cut += 1) {
    const decoded = decodeLog(log.slice(0, cut));
    assert.deepEqual(decoded.records, records.slice(0, decoded.records.length), `prefix at ${cut}`);
    assert.ok(decoded.records.length >= previous, `record count never falls at ${cut}`);
    assert.ok(decoded.bytesUsed <= cut, `never consumes past the cut at ${cut}`);
    assert.equal(decoded.truncated, !boundaries.has(cut), `truncation flag at ${cut}`);
    previous = decoded.records.length;
  }
  assert.equal(previous, records.length);
});

test('a corrupted frame ends the scan without throwing', () => {
  const records = [
    { t: 'put', k: 'a', v: 'one' },
    { t: 'put', k: 'b', v: 'two' },
    { t: 'put', k: 'c', v: 'three' },
  ];
  const first = encodeRecord(records[0]).length;
  const second = encodeRecord(records[1]).length;

  const flipped = buildLog(records);
  flipped[first + HEADER_BYTES + 2] ^= 0xff;
  const afterFlip = decodeLog(flipped);
  assert.deepEqual(afterFlip.records, [records[0]]);
  assert.equal(afterFlip.bytesUsed, first);
  assert.equal(afterFlip.truncated, true);

  const badLength = buildLog(records);
  badLength[first] = 0xff;
  const afterLength = decodeLog(badLength);
  assert.deepEqual(afterLength.records, [records[0]]);
  assert.equal(afterLength.truncated, true);

  const trailing = buildLog(records);
  const withGarbage = new Uint8Array(trailing.length + 5);
  withGarbage.set(trailing, 0);
  withGarbage.set(new Uint8Array([1, 2, 3, 4, 5]), trailing.length);
  const afterGarbage = decodeLog(withGarbage);
  assert.deepEqual(afterGarbage.records, records);
  assert.equal(afterGarbage.bytesUsed, first + second + encodeRecord(records[2]).length);
  assert.equal(afterGarbage.truncated, true);
});

test('decodeLog survives arbitrary bytes', () => {
  const pick = mulberry32(2468);
  for (let round = 0; round < 200; round += 1) {
    const length = Math.floor(pick() * 40);
    const bytes = new Uint8Array(length);
    for (let index = 0; index < length; index += 1) bytes[index] = Math.floor(pick() * 256);
    const decoded = decodeLog(bytes);
    assert.ok(Array.isArray(decoded.records), 'always returns a record list');
    assert.ok(decoded.bytesUsed >= 0 && decoded.bytesUsed <= bytes.length, 'consumes a real prefix');
    assert.equal(typeof decoded.truncated, 'boolean');
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { KvStore, decodeLog } from '../src/index.js';

/** Deterministic 32-bit PRNG so generated operation sequences replay identically. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Fold decoded records into sorted entries, independently of the store. */
function fold(records) {
  const map = new Map();
  for (const record of records) {
    if (record.t === 'put') map.set(record.k, record.v);
    else map.delete(record.k);
  }
  return [...map.keys()].sort().map((key) => [key, map.get(key)]);
}

test('a fresh store is empty and readable', () => {
  const store = new KvStore();
  assert.equal(store.size, 0);
  assert.deepEqual(store.keys(), []);
  assert.deepEqual(store.entries(), []);
  assert.equal(store.get('missing'), undefined);
  assert.equal(store.has('missing'), false);
